// A libFuzzer entry point for complete files.

import RasterWebPCore
import RasterWebPDecoder

/// Decodes one input generated by libFuzzer.
@_cdecl("LLVMFuzzerTestOneInput")
public func fuzzDecoder(_ data: UnsafePointer<UInt8>?, _ count: Int) -> CInt {
    let bytes = UnsafeBufferPointer(start: data, count: count)

    var options = WebPDecodingOptions()
    options.limits.maximumPixelCount = 1 << 20
    options.limits.maximumMemoryByteCount = 1 << 26

    if let image = try? WebPDecoder.decode(bytes.span, options: options) {
        precondition(image.pixels.count == image.width * image.height * 4)
    }
    return 0
}
